using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — fixes for EF Core 9 breaking changes:
// 1. Discriminator property renamed from "Discriminator" to "$type" — preserve old name
// 2. id property no longer contains discriminator — preserve old compound format
// 3. Sync I/O no longer supported — use async methods

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix: EF Core 9 changed default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so explicitly configure the old name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix: EF Core 9 no longer includes the discriminator in the JSON id property.
        // Existing documents have compound ids like "Session|<key>".
        // Preserve old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string UserId { get; set; } = default!;
    public DateTime ExpiresAt { get; set; }
}

// Fix: Cosmos DB provider no longer supports synchronous I/O in EF Core 9.
// All queries and SaveChanges must use async equivalents.
class CosmosSessionService
{
    private readonly CosmosDbContext _db;

    public CosmosSessionService(CosmosDbContext db) => _db = db;

    // BEFORE (breaks in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.UserId == userId).ToList();
    //   _db.SaveChanges();
    //
    // AFTER: use async methods
    public async Task<List<Session>> GetSessionsAsync(string userId)
    {
        return await _db.Sessions
            .Where(s => s.UserId == userId)
            .ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

